mkdir -p "$REPRO"

REPRO_DIR="$REPRO" node --input-type=module -e '
import { existsSync } from "node:fs";
import { join } from "node:path";
import { PiboDataStore } from "./dist/data/pibo-store.js";
import { ChatDataIngestService } from "./dist/data/ingest-service.js";
import { ChatSessionQueryService } from "./dist/apps/chat/data/session-query-service.js";
import { createPiboSession } from "./dist/sessions/store.js";

const root = process.env.REPRO_DIR;
const dbPath = join(root, "pibo.sqlite");
const payloadRoot = join(root, "payloads");
const session = createPiboSession({
  id: "ps_synthetic_payload_delete",
  piSessionId: "pi_synthetic_payload_delete",
  channel: "pibo.chat-web",
  kind: "interactive",
  profile: "base",
  metadata: { chatRoomId: "room_synthetic_payload_delete" },
}, "2026-08-30T02:45:00.000Z");
const text = "SYNTHETIC-LARGE-MESSAGE-".repeat(1200);

let store = new PiboDataStore(dbPath, { payloadRootDir: payloadRoot });
const result = new ChatDataIngestService(store).ingestUserMessageAccepted({
  session,
  roomId: "room_synthetic_payload_delete",
  actorId: "synthetic-user",
  text,
  clientTxnId: "txn-synthetic-payload-delete",
