const message = store.db.prepare(
  "SELECT content_payload_ref FROM chat_messages WHERE id = ?",
).get(result.messageId);
const payload = store.payloads.getPayload(message.content_payload_ref);
const file = join(payloadRoot, payload.storagePath);

console.log("before", {
  refCount: payload.refCount,
